using System;
using System.Threading;
using System.Threading.Tasks;

namespace ZeroCue.DataProbe.Services
{
    public enum AckValidationMode
    {
        ReplayTolerant,
        StrictStatusZero
    }

    public class DeviceModeController
    {
        private readonly System.Threading.SemaphoreSlim _usbLock;
        private readonly ScufAckReader _ackReader;
        private readonly IScufRawTransport _transport;
        private readonly Action<string> _logger;
        private readonly ScufProtocolProfile _profile;

        public DeviceModeController(System.Threading.SemaphoreSlim usbLock, ScufAckReader ackReader, IScufRawTransport transport, Action<string> logger, ScufProtocolProfile? profile = null)
        {
            _usbLock = usbLock ?? throw new ArgumentNullException(nameof(usbLock));
            _ackReader = ackReader ?? throw new ArgumentNullException(nameof(ackReader));
            _transport = transport ?? throw new ArgumentNullException(nameof(transport));
            _logger = logger;
            _profile = profile ?? ScufProtocolProfile.Wired;
        }

        public bool IsHandshakeActive { get; private set; } = false;

        private static byte[] BuildRuntimeReport(byte runtimeChannel, byte opcode, byte subOpcode, params byte[] payload)
        {
            var report = new byte[64];
            report[0] = 0x02;
            report[1] = runtimeChannel;
            report[2] = opcode;
            report[3] = subOpcode;

            if (payload.Length > 0)
            {
                Buffer.BlockCopy(payload, 0, report, 4, Math.Min(payload.Length, report.Length - 4));
            }

            return report;
        }

        public async Task<byte[]> SendReportAndWaitAckAsync(byte[] report, byte expectedOpcode, CancellationToken ct, AckValidationMode validationMode)
        {
            await _usbLock.WaitAsync(ct);
            try
            {
                var expectedAckChannel = report.Length > 1 && report[1] == _profile.InitCommandChannel
                    ? _profile.InitAckChannel
                    : _profile.RuntimeAckChannel;
                byte status = await _ackReader.SendCommandAndWaitAckAsync(report, expectedAckChannel, expectedOpcode, ct, validationMode == AckValidationMode.StrictStatusZero);
                if (validationMode == AckValidationMode.StrictStatusZero && status != 0x00)
                {
                    throw new Exception($"ACK Error status 0x{status:X2} para Opcode 0x{expectedOpcode:X2}");
                }
                return new byte[] { 0x01, 0x00, expectedOpcode, status };
            }
            finally
            {
                _usbLock.Release();
            }
        }


