        public Task EnterSoftwareModeAsync(CancellationToken ct)
        {
            return EnterSoftwareModeAsync(ct, AckValidationMode.StrictStatusZero);
        }

        private async Task EnterSoftwareModeAsync(CancellationToken ct, AckValidationMode validationMode)
        {
            _logger($"--- ENTRANDO EN SOFTWARE MODE validation={validationMode} ---");
            IsHandshakeActive = true;
            try
            {
                // Report 1: 0D
                var r1 = new byte[64];
                r1[0] = 0x02; r1[1] = _profile.RuntimeCommandChannel; r1[2] = 0x0D; r1[3] = 0x01; r1[4] = 0x02;
                await SendReportAndWaitAckAsync(r1, 0x0D, ct, validationMode);

                // Report 2: 06
                var r2 = new byte[64];
                r2[0] = 0x02; r2[1] = _profile.RuntimeCommandChannel; r2[2] = 0x06; r2[3] = 0x01; r2[4] = 0x20;
                for (int i = 0; i < 32; i++) r2[8 + i] = 0x01;
                r2[8 + 30] = 0x00;
                await SendReportAndWaitAckAsync(r2, 0x06, ct, validationMode);

                // Report 3: 05
                var r3 = new byte[64];
                r3[0] = 0x02; r3[1] = _profile.RuntimeCommandChannel; r3[2] = 0x05; r3[3] = 0x01; r3[4] = 0x01;
                await SendReportAndWaitAckAsync(r3, 0x05, ct, validationMode);

                _logger("[SUCCESS] Entrado en Software Mode correctamente.");
            }
            finally
            {
                IsHandshakeActive = false;
            }
        }

        public async Task SuppressG5HardwareEcoToggleAsync(CancellationToken ct)
        {
            _logger($"[G5] Suppressor START kind={_profile.ConnectionKind} runtimeChannel=0x{_profile.RuntimeCommandChannel:X2} ackChannel=0x{_profile.RuntimeAckChannel:X2} disabledMaskIndex=30");
            var validationMode = _profile.ConnectionKind == ScufConnectionKind.Wireless
                ? AckValidationMode.ReplayTolerant
                : AckValidationMode.StrictStatusZero;

            await EnterSoftwareModeAsync(ct, validationMode);
            await ApplyG5FakeMappingAsync(ct);
            _logger("[G5] Suppressor DONE: software mask + fake mapping sequence ACKed.");
        }

