        private async Task SendG5FakeMappingReportAsync(string name, byte opcode, byte subOpcode, byte expectedOpcode, CancellationToken ct, params byte[] payload)
        {
            var report = BuildRuntimeReport(_profile.RuntimeCommandChannel, opcode, subOpcode, payload);
            _logger($"[G5] Fake mapping report {name} opcode=0x{opcode:X2} sub=0x{subOpcode:X2} bytes={payload.Length + 4}");
            await SendReportAndWaitAckAsync(report, expectedOpcode, ct, AckValidationMode.ReplayTolerant);
        }

