        {
            StopIcueKeepAliveAsync().Wait();
            _keepAliveCts = new CancellationTokenSource();
            _keepAliveTask = Task.Run(() => KeepAliveLoopAsync(_keepAliveCts.Token));
            _logger("[SYSTEM] iCUE Keepalive iniciado.");
        }

        public async Task StopIcueKeepAliveAsync()
        {
            if (_keepAliveCts != null)
            {
                _keepAliveCts.Cancel();
                if (_keepAliveTask != null)
                {
                    try { await _keepAliveTask; } catch { }
                }
                _keepAliveCts.Dispose();
                _keepAliveCts = null;
            }
        }

        private async Task KeepAliveLoopAsync(CancellationToken ct)
        {
            var report = new byte[64];
            report[0] = 0x02; report[1] = _profile.RuntimeCommandChannel; report[2] = 0x12; report[3] = 0x00;

            while (!ct.IsCancellationRequested)
            {
                try
                {
                    await Task.Delay(10000, ct); // 10 seconds
                    await SendReportAndWaitAckAsync(report, 0x12, ct, AckValidationMode.StrictStatusZero);
                    _logger("[KEEPALIVE] OK");
                }
                catch (TaskCanceledException) { break; }
                catch (Exception ex)
                {
                    _logger($"[KEEPALIVE] FAIL: {ex.Message}");
                }
            }
        }

        public async Task SetStaticRgbAsync(byte r, byte g, byte b, CancellationToken ct)
        {
            var report = new byte[64];
            report[0] = 0x02; report[1] = _profile.RuntimeCommandChannel; report[2] = 0x06; report[3] = 0x00;
            report[4] = 0x1B; report[5] = 0x00; report[6] = 0x00; report[7] = 0x00;

            for (int i = 0; i < 9; i++) report[8 + i] = r;
            for (int i = 0; i < 9; i++) report[17 + i] = g;
            for (int i = 0; i < 9; i++) report[26 + i] = b;

            _logger($"[RGB] Setting static color R:{r} G:{g} B:{b}");
            await SendReportAndWaitAckAsync(report, 0x06, ct, AckValidationMode.StrictStatusZero);

            if (_profile.ConnectionKind == ScufConnectionKind.Wireless)
            {
                var commitReport = new byte[64];
                commitReport[0] = 0x02; commitReport[1] = _profile.RuntimeCommandChannel; commitReport[2] = 0x02; commitReport[3] = 0x0F;
                commitReport[4] = 0x00;
                await SendReportAndWaitAckAsync(commitReport, 0x02, ct, AckValidationMode.StrictStatusZero);
                await Task.Delay(100, ct);
                await SendReportAndWaitAckAsync(commitReport, 0x02, ct, AckValidationMode.StrictStatusZero);
            }
        }

        public async Task SetBrightnessAsync(ushort value, CancellationToken ct)
        {
            if (value > 1000) value = 1000;

            // iCUE uses 660 (0x0294) for 100% brightness. We apply gamma correction for smooth transitions.
            double normalized = value / 1000.0;
            double curved = Math.Pow(normalized, 2.0);
            ushort scaledValue = (ushort)(curved * 660);

            var report = new byte[64];
            report[0] = 0x02; report[1] = _profile.RuntimeCommandChannel; report[2] = 0x01; report[3] = 0x02;
            report[4] = 0x00;
            report[5] = (byte)(scaledValue & 0xFF);
            report[6] = (byte)((scaledValue >> 8) & 0xFF);

            _logger($"[BRIGHTNESS] Setting brightness to {scaledValue} (UI: {value})");
            var ack = await SendReportAndWaitAckAsync(report, 0x01, ct, AckValidationMode.StrictStatusZero);

            ZeroCueLog.Communication($"[BRIGHTNESS] Request UI={value}, scaled={scaledValue}, hex={report[5]:X2} {report[6]:X2}, ACK={BitConverter.ToString(ack)}");

            if (_profile.ConnectionKind == ScufConnectionKind.Wireless)
            {
                var commitReport = new byte[64];
                commitReport[0] = 0x02; commitReport[1] = _profile.RuntimeCommandChannel; commitReport[2] = 0x02; commitReport[3] = 0x02;
                commitReport[4] = 0x00;
                await SendReportAndWaitAckAsync(commitReport, 0x02, ct, AckValidationMode.StrictStatusZero);
                await Task.Delay(100, ct);
                await SendReportAndWaitAckAsync(commitReport, 0x02, ct, AckValidationMode.StrictStatusZero);
            }
        }

        public async Task SetEcoModeAsync(bool enabled, CancellationToken ct)
        {
            var report = new byte[64];
            report[0] = 0x02; report[1] = _profile.RuntimeCommandChannel; report[2] = 0x01; report[3] = 0x0B;
            report[4] = 0x00; report[5] = (byte)(enabled ? 0x01 : 0x00);

            _logger($"[ECO] Setting ECO Mode to {enabled}");
            await SendReportAndWaitAckAsync(report, 0x01, ct, AckValidationMode.StrictStatusZero);
        }

        public async Task SetRumbleIntensityAsync(byte value, CancellationToken ct)
        {
            _logger($"[RUMBLE] Setting persistent rumble intensity to {value}%");

            await SendRumbleSettingReportAsync(0x84, value, ct);
            await SendRumbleSettingReportAsync(0x85, value, ct);
        }

        private async Task SendRumbleSettingReportAsync(byte subOpcode, byte value, CancellationToken ct)
        {
            var report = new byte[64];
            report[0] = 0x02;
            report[1] = _profile.RuntimeCommandChannel;
            report[2] = 0x01;
            report[3] = subOpcode;
            report[4] = 0x00;
            report[5] = value;

            await SendReportAndWaitAckAsync(report, 0x01, ct, AckValidationMode.StrictStatusZero);
        }


        public async Task InitializeDeviceInSoftwareModeAsync(CancellationToken ct)
        {
            await InitializeIcueSessionAsync(ct);
            await EnterSoftwareModeAsync(ct);
            StartIcueKeepAlive();
        }
    }
}
